def run(context, tools):
    origin = context.get('origin')
    destination = context.get('destination')
    departure_date = context.get('departure_date')
    passengers = context.get('passengers')
    flight_number = context.get('flight_number')

    def is_iata(code):
        return isinstance(code, str) and len(code) == 3 and code.isalpha() and code.upper() == code

    missing = []
    if origin is None or (isinstance(origin, str) and origin.strip() == ''):
        missing.append('origin')
    if destination is None or (isinstance(destination, str) and destination.strip() == ''):
        missing.append('destination')
    if departure_date is None or (isinstance(departure_date, str) and departure_date.strip() == ''):
        missing.append('departure_date')
    if passengers is None or (isinstance(passengers, str) and passengers.strip() == ''):
        missing.append('passengers')

    if missing:
        return {'result': {'message': 'Missing required field(s): ' + ', '.join(missing) + '. Please provide them.', 'status': 'no_flights'}}

    if not is_iata(origin):
        return {'result': {'message': 'Origin must be a 3-letter IATA airport code (e.g. MEL). Please provide the airport code, not a city name.', 'status': 'no_flights'}}
    if not is_iata(destination):
        return {'result': {'message': 'Destination must be a 3-letter IATA airport code (e.g. SYD). Please provide the airport code, not a city name.', 'status': 'no_flights'}}

    has_flight = flight_number is not None and (not isinstance(flight_number, str) or flight_number.strip() != '')
    phase = 'book' if has_flight else 'search'

    return {'result': {'phase': phase, 'origin': origin, 'destination': destination, 'departure_date': departure_date, 'passengers': passengers, 'flight_number': flight_number}}

def run(context, tools):
    origin = context.get('origin')
    destination = context.get('destination')
    departure_date = context.get('departure_date')
    passengers_raw = context.get('passengers')
    flight_number = context.get('flight_number')

    def is_iata(code):
        return isinstance(code, str) and len(code) == 3 and code.isalpha() and code.upper() == code

    if flight_number is None or (isinstance(flight_number, str) and flight_number.strip() == ''):
        return {'result': {'message': 'A flight_number is required to book. Please choose a flight from the options first.', 'status': 'no_flights'}}
    if departure_date is None or (isinstance(departure_date, str) and departure_date.strip() == ''):
        return {'result': {'message': 'A departure date is required to book.', 'status': 'no_flights'}}
    if not is_iata(origin):
        return {'result': {'message': 'Origin must be a 3-letter IATA airport code.', 'status': 'no_flights'}}
    if not is_iata(destination):
        return {'result': {'message': 'Destination must be a 3-letter IATA airport code.', 'status': 'no_flights'}}

    if isinstance(passengers_raw, str):
        parts = [p.strip() for p in passengers_raw.split(',') if p.strip()]
    elif isinstance(passengers_raw, list):
        parts = passengers_raw
    else:
        return {'result': {'message': 'Passengers must be a comma-separated string or list, e.g. "John Doe (adult), Mary Doe (child)".', 'status': 'no_flights'}}

    passengers = []
    has_adult = False
    for p in parts:
        name = p
        ptype = 'adult'
        if isinstance(p, str) and '(' in p and ')' in p:
            i = p.rfind('(')
            name = p[:i].strip()
            ptype = p[i+1:p.rfind(')')].strip().lower()
        if 'adult' in str(ptype):
            has_adult = True
            ptype = 'adult'
        elif 'child' in str(ptype) or 'infant' in str(ptype):
            pass
        else:
            ptype = 'adult'
            has_adult = True
        passengers.append({'name': name, 'type': ptype})

    if not has_adult:
        return {'result': {'message': 'A child or infant cannot travel without at least one adult on the same booking. Please include at least one adult.', 'status': 'no_flights'}}

    book_resp = tools.call('mcp-demo____bookTicket', {'flight_id': flight_number, 'passengers': passengers})
    booking = book_resp['booking']
    pnr = booking['pnr']

    pay_resp = tools.call('mcp-demo____generatePaymentLink', {'pnr': pnr})
    payment = pay_resp['payment']
    payment_link = payment['payment_url']
    amount_due = payment['amount']

    return {'result': {
        'message': 'Booking confirmed for ' + str(len(passengers)) + ' passenger(s) on flight ' + str(flight_number) + '. Payment completed.',
        'status': 'paid',
        'pnr': pnr,
        'flight_number': flight_number,
        'origin': origin,
        'destination': destination,
        'departure': departure_date,
        'passenger_count': len(passengers),
        'amount_due': amount_due,
        'payment_link': payment_link
    }}
